const groupLogsByType = <
  T extends { BuildLog: { index: number } } // assuming BuildLog has an index property
>(
  rawLogs: T['BuildLog'][],
  filterType: FilterState,
) => {
  const FILTER_TYPES = { all: 'all', errors: 'errors', warnings: 'warnings' };
  constlogTypes = rawLogs.map((l, index) => ({ ...l, index }));

  if (FILTER_TYPES[filterType] === 'all' || logTypes.length === 0) {
    return [{ hidden: false, logs: logTypes }];
  }

  return group(logTypes, filterType).map((group) => ({
    hidden: groupType !== filterType,
    logs: group,
  }));

  function group(logs, filterType) {
    const result = [[]];
    let currentGroupType = result[0].length === 0 ? 'all' : result[result.length - 1][0].type;

    for (const log of logs) {
      const logType = log.error ? 'errors' : log.warning ? 'warnings' : 'all';

      if (logType !== currentGroupType) {
        result.push([log]);
        currentGroupType = logType;
      } else {
        result[result.length - 1].push(log);
      }
    }

    return result.map((group) => ({ logs: group }));
  }
};
```

