Here is a basic JavaScript code that uses HTML5 canvas to render a pendulum and simulates its swinging motion based on the laws of physics:

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Pendulum Simulation</title>
  <style>
    canvas {
      border: 1px solid black;
    }
  </style>
</head>
<body>
  <button id="start-button">Release Pendulum</button>
  <canvas id="pendulum-canvas" width="400" height="400"></canvas>
  <script>
    let canvas = document.getElementById('pendulum-canvas');
    let ctx = canvas.getContext('2d');
    let canvasWidth = canvas.width;
    let canvasHeight = canvas.height;
    let pendulumLength = 200;
    let initialAngle = 0;
    let angle = 0;
    let velocity = 0;
    let gravity = 0.0981; // 9.81 m/s^2
    let timeStep = 0.02; // seconds
    let simulationRunning = false;

    function drawPendulum() {
      ctx.clearRect(0, 0, canvasWidth, canvasHeight);
      ctx.strokeStyle = 'black';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(canvasWidth / 2, canvasHeight / 2, pendulumLength / 2, 0, 2 * Math.PI);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(canvasWidth / 2, canvasHeight / 2);
      ctx.lineTo(canvasWidth / 2 + pendulumLength / 2 * Math.sin(angle), canvasHeight / 2 - pendulumLength / 2 * Math.cos(angle));
      ctx.stroke();
    }

    function updatePendulum() {
      if (!simulationRunning) return;
      angle += velocity * timeStep;
      velocity += gravity * Math.sin(angle) * timeStep;
      if (Math.abs(velocity) < 0.01) {
        simulationRunning = false;
      }
    }

    function startSimulation() {
      simulationRunning = true;
      initialAngle = prompt('Enter the initial angle in degrees:', '10');
      angle = Math.radians(initialAngle);
      velocity = 0;
      drawPendulum();
      setInterval(function() {
        updatePendulum();
        drawPendulum();
      }, 16); // 16ms = 60fps
    }

    function Math.radians(degrees) {
      return degrees * (Math.PI / 180);
    }

    document.getElementById('start-button').addEventListener('click', startSimulation);

    drawPendulum();
  </script>
</body>
</html>
```

This code creates a canvas element and sets up a simulation that updates every 16 milliseconds (roughly 60 frames per second). The initial angle of the pendulum is taken as an input from the user. The pendulum's angle and velocity are updated based on the laws of physics, and the simulation continues until the pendulum comes to rest.

You can adjust the `timeStep` variable to change the accuracy of the simulation. A smaller `timeStep` will produce a more accurate simulation, but will also increase the computational load.

