				log.Println("Deleting", snapshot.SnapshotId)
				err := deleteSnapshot(ec2Svc, snapshot.SnapshotId)
				if err != nil {
					return nil, err
				}
			} else if backupType == "daily" && len(snapshots) > 10 {
				log.Println("Deleting", snapshot.SnapshotId)
				err := deleteSnapshot(ec2Svc, snapshot.SnapshotId)
				if err != nil {
					return nil, err
				}
			} else if backupType == "weekly" && len(snapshots) > 4 {
