}

func getSnapshots(ec2Svc *ec2.EC2) ([]*ec2.Snapshot, error) {
	snapshots := []*ec2.Snapshot{}
	err := ec2Svc.DescribeSnapshotsPages(&ec2.DescribeSnapshotsInput{}, func(page *ec2.DescribeSnapshotsOutput, lastPage bool) bool {
		for _, snapshot := range page.Snapshots {
			snapshots = append(snapshots, snapshot)
		}
		return !lastPage
	})
	if err != nil {
		return nil, err
	}
	return snapshots, nil
}

func groupSnapshotsByType(snapshots []*ec2.Snapshot) map[string][]*ec2.Snapshot {
	groupedSnapshots := make(map[string][]*ec2.Snapshot)
	for _, snapshot := range snapshots {
		tag, ok := getTagValue(snapshot.Tags, "backup_type")
		if ok {
			if _, exists := groupedSnapshots[tag]; !exists {
				groupedSnapshots[tag] = []*ec2.Snapshot{}
			}
			groupedSnapshots[tag] = append(groupedSnapshots[tag], snapshot)
		}
	}
	return groupedSnapshots
}

func getTagValue(tags []*ec2.Tag, key string) (string, bool) {
	for _, tag := range tags {
		if *tag.Key == key {
			return *tag.Value, true
		}
	}
	return "", false
}

func deleteSnapshot(ec2Svc *ec2.EC2, snapshotId string) error {
	_, err := ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: aws.String(snapshotId)})
	return err
}

func main() {
	lambda.Start(handler)
}
