    // Initialize the pigpio library
    if (pigpioInitialise() < 0) {
        std::cerr << "pigpio initialization failed" << std::endl;
        return 1;
    }

    // Set the mode of the GPIO pin to output
    gpioSetup(GPIO_PIN, PI_OUTPUT);

    // Set the initial state of the GPIO pin to LOW (0)
    gpioWrite(GPIO_PIN, PI_LOW);

    // Loop until the program is interrupted
    while (true) {
        // Set the GPIO pin to HIGH (1) for 1 second
        gpioWrite(GPIO_PIN, PI_HIGH);
        delay(1000);
        // Set the GPIO pin to LOW (0) for 1 second
        gpioWrite(GPIO_PIN, PI_LOW);
        delay(1000);
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}
